export type ResearchTextSegment =
  | { kind: "text"; text: string }
  | { kind: "link"; text: string; href: string; external: boolean };

const linkPattern = /\[([^\]]+)\]\(([^)\s]+)\)/g;

/**
 * Split research copy into plain text and links. Research page text is
 * generated by the build scripts and may contain `[label](href)` links only;
 * no other markup is interpreted.
 */
export function researchTextSegments(text: string): ResearchTextSegment[] {
  const segments: ResearchTextSegment[] = [];
  let last = 0;
  for (const match of text.matchAll(linkPattern)) {
    const index = match.index ?? 0;
    if (index > last) {
      segments.push({ kind: "text", text: text.slice(last, index) });
    }
    const href = match[2];
    segments.push({
      kind: "link",
      text: match[1],
      href,
      external: /^https?:\/\//.test(href),
    });
    last = index + match[0].length;
  }
  if (last < text.length)
    segments.push({ kind: "text", text: text.slice(last) });
  return segments;
}

/** Plain text for metadata and structured data: links keep only their label. */
export function researchPlainText(text: string) {
  return text.replace(linkPattern, "$1");
}

const longDate = new Intl.DateTimeFormat("en-US", {
  month: "long",
  day: "numeric",
  year: "numeric",
  timeZone: "UTC",
});

export function formatResearchDate(isoDate: string) {
  return longDate.format(new Date(`${isoDate}T00:00:00Z`));
}
